argv:
python3 - <<'PY'
p='src/solver.cpp'
s=open(p).read()
needle='    void improve(State& s) {\n'
replacement='''    void improve(State& s) {
        // Move individual customers between routes, retaining exact feasibility.
        for(int pass=0;pass<40;pass++) {
            double bestDelta=-1e-7;int from=-1,to=-1,at=-1,pos=-1;
            for(int a=0;a<(int)s.size();a++)for(int p=0;p<(int)s[a].q.size();p++) {
                int c=s[a].q[p],prev=p?s[a].q[p-1]:0;
                int next=p+1<(int)s[a].q.size()?s[a].q[p+1]:0;
                double saving=d[prev][next]-d[prev][c]-d[c][next];
                if(s[a].q.size()==1)saving-=1500;
                for(int b=0;b<(int)s.size();b++)if(a!=b)
                    for(int k=0;k<=(int)s[b].q.size();k++) {
                        double delta=saving+insertion(s[b],c,k);
                        if(delta<bestDelta){bestDelta=delta;from=a;to=b;at=p;pos=k;}
                    }
            }
            if(from<0)break;
            int c=s[from].q[at];s[from].q.erase(s[from].q.begin()+at);
            s[to].q.insert(s[to].q.begin()+pos,c);update(s[from]);update(s[to]);prune(s);
        }
'''
assert needle in s;s=s.replace(needle,replacement)
open(p,'w').write(s)
PY
make
